/** Label tampilan untuk pengelompokan pada antarmuka */
export const LABEL_RANAH = {
  A: 'A. Pendidikan',
  B: 'B. Penelitian',
  C: 'C. Pengabdian kepada Masyarakat',
  D: 'D. Tata Kelola dan Kelembagaan',
  E: 'E. Keberlanjutan dan Lingkungan Kampus',
};

export const LABEL_KELOMPOK = { L: 'Luaran', P: 'Proses', M: 'Masukan' };

export function labelKategori(ranah, kelompok) {
  const r = LABEL_RANAH[ranah] || ranah;
  return kelompok ? `${r} — ${LABEL_KELOMPOK[kelompok]}` : r;
}